def registros_para_itens(apps, schema_editor):
    """Cada registro antigo (um serviço só) vira um registro com 1 item: mesmo serviço, mesmo valor, mesmo atendimento.
    Nada é apagado nem alterado nos registros, atendimentos e recebimentos."""
    Registro, Item = apps.get_model("vip_preparacao", "RegistroVip"), apps.get_model("vip_preparacao", "ItemServicoVip")
    for r in Registro.objects.filter(servico__isnull=False).iterator():
        if not Item.objects.filter(registro_id=r.pk).exists():
            Item.objects.create(registro_id=r.pk, servico_id=r.servico_id, valor=r.valor, atendimento_id=r.atendimento_id)


def itens_para_registros(apps, schema_editor):
    """Volta: o serviço e o atendimento do registro vêm do primeiro item (o valor do registro já é o total)."""
    Registro, Item = apps.get_model("vip_preparacao", "RegistroVip"), apps.get_model("vip_preparacao", "ItemServicoVip")
    for r in Registro.objects.iterator():
        primeiro = Item.objects.filter(registro_id=r.pk).order_by("id").first()
        if primeiro:
            Registro.objects.filter(pk=r.pk).update(servico_id=primeiro.servico_id, atendimento_id=primeiro.atendimento_id)


